            })

        resp = client.put_events(Entries=entries)
        return {
            "ok": resp.get("FailedEntryCount", 0) == 0,
            "n_failed": resp.get("FailedEntryCount", 0),
            "n_published": len(entries) - resp.get("FailedEntryCount", 0),
        }
    except Exception as e:
